-- ===== Project: Automatic Fire Extinguisher Robotic Car (fire-extinguisher-robotic-car) =====
do $seed$
declare c uuid; m uuid; q uuid; qq uuid;
begin
  if exists (select 1 from courses where slug = 'fire-extinguisher-robotic-car') then
