  insert into courses(title,slug,description,difficulty_level,is_published,total_lessons,total_quizzes,estimated_duration_minutes)
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 1: Introduction to robotics$t$,$t$Understand robotics, why robots matter, and meet the parts of your kit.$t$,1) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What is robotics?$t$,$t$<p><strong>🎯 Objective:</strong> Explain what robotics is, what a robot is, and why robots are important.</p><h3>What is robotics?</h3><p>Robotics is a branch of engineering and technology that deals with the making of robots.</p><h3>What is a robot?</h3><p>A robot is a machine that has been programmed to automatically make work easier.</p><h3>Examples of robots</h3><ul><li>Lifts</li><li>Drones</li><li>Microwaves</li><li>Traffic lights</li></ul><h3>Why robots are important</h3><ul><li>They make work easier, for example a lift.</li><li>They save time, for example a microwave.</li></ul><h3>Robots that use sensors</h3><p>Some robots sense the world around them. An <strong>obstacle-avoiding robot</strong> uses sensors to avoid hitting objects. Other examples are a <strong>line-following robot</strong>, a <strong>light-following robot</strong> and a <strong>sound-activated robot</strong>.</p><h3>Check yourself</h3><ul><li>Name two robots you have seen at home, at school or on the road.</li><li>Which one saves time? Which one makes work easier?</li></ul>$t$,null,$t$A robot is a machine that is programmed to do work automatically.$t$,1,8),
    (m,$t$Meet your kit$t$,$t$<p><strong>🎯 Objective:</strong> Name the main parts of your kit and say what each one does.</p><h3>The SmartBrains Arduino</h3><p>This is the brain of your robot. It has <strong>inputs</strong>, which receive data, and <strong>outputs</strong>, which send data out.</p><p><em>📷 Picture to be added: the SmartBrains Arduino with the input and output parts labelled</em></p><h3>The breadboard</h3><p>A breadboard lets you join parts together without soldering. Holes in the same row are connected inside, and the long strips along the sides carry power (+) and ground (-).</p><p><em>📷 Picture to be added: a breadboard showing how current flows along rows and the power strips</em></p><h3>Jumper wires</h3><p>Jumper wires connect the Arduino to the breadboard. There are three types:</p><ul><li><strong>Pin to pin</strong>: a metal pin on both ends.</li><li><strong>Pin to port</strong>: a pin on one end and a socket on the other.</li><li><strong>Port to port</strong>: a socket on both ends.</li></ul><h3>Resistors</h3><p>A resistor reduces the current that flows to parts like LEDs, so that they are not damaged.</p><h3>Check yourself</h3><ul><li>Which part joins components together without soldering?</li><li>What does a resistor protect?</li></ul>$t$,null,$t$Breadboard = no soldering. Resistor = protects the LED.$t$,2,12),
    (m,$t$LEDs: anode and cathode$t$,$t$<p><strong>🎯 Objective:</strong> Say what LED stands for and tell the anode from the cathode.</p><p><strong>LED</strong> stands for <strong>Light Emitting Diode</strong>. LEDs light up to show different states, for example on, off, ready or stop.</p><p>In electronics, electricity travels along two separate wires. An LED has two legs, one for each charge:</p><table><thead><tr><th>Leg</th><th>Charge</th><th>Name</th></tr></thead><tbody><tr><td>Longer leg</td><td>Positive (+)</td><td><strong>Anode</strong></td></tr><tr><td>Shorter leg</td><td>Negative (-)</td><td><strong>Cathode</strong></td></tr></tbody></table><p><em>📷 Picture to be added: an LED with the longer leg (anode) and shorter leg (cathode) labelled; the two-finger demonstration</em></p><h3>Check yourself</h3><ul><li>Which leg is longer, the anode or the cathode?</li><li>Which leg goes towards the negative side of a circuit?</li></ul>$t$,null,$t$Longer leg = positive = Anode. Shorter leg = negative = Cathode.$t$,3,8),
    (m,$t$Connect your board to the laptop$t$,$t$<p><strong>🎯 Objective:</strong> Power up your SmartBrains Arduino using the USB cable.</p><h3>Steps</h3><ol><li>Plug the small end of the USB cable into your SmartBrains Arduino.</li><li>Plug the other end into your laptop.</li><li>Check that the lights on your board come on.</li></ol><p>If your board does not light up, raise your hand and ask your teacher for help.</p>$t$,null,$t$If the board lights up, it has power.$t$,4,5);
