  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 3: Building a simple circuit (practical)$t$,$t$Build a real circuit with three LEDs and get them all lighting up.$t$,3) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Plan and stay safe$t$,$t$<p><strong>🎯 Objective:</strong> Gather your tools and learn the safety rule for powering a circuit.</p><h3>You need</h3><ul><li>SmartBrains Arduino</li><li>Breadboard</li><li>Jumper wires</li><li>3 LEDs (green, red and yellow)</li><li>USB cable (your teacher hands this out)</li></ul><p><strong>⚠ Caution:</strong> Your teacher will only give you the USB cable after checking your wiring. The USB cable is what powers the circuit, and if the connections are wrong the circuit can burn. Never plug in before your teacher says so.</p>$t$,null,$t$No USB cable until your teacher has checked your wiring.$t$,1,5),
    (m,$t$Power the breadboard$t$,$t$<p><strong>🎯 Objective:</strong> Connect the power and ground of the Arduino to the breadboard.</p><h3>Steps</h3><ol><li>Take your SmartBrains Arduino.</li><li>Find the <strong>GND</strong> (ground) and <strong>3.3V</strong> ports.</li><li>Take a pin-to-pin jumper wire. Connect one end to GND and the other end to the <strong>negative</strong> port of the breadboard.</li><li>Take another pin-to-pin wire. Connect 3.3V to the <strong>positive</strong> port of the breadboard.</li></ol><p><em>📷 Picture to be added: GND to the negative rail and 3.3V to the positive rail</em></p>$t$,null,$t$GND to negative. 3.3V to positive.$t$,2,10),
    (m,$t$Place and connect the LEDs$t$,$t$<p><strong>🎯 Objective:</strong> Place three LEDs on the breadboard and connect them the right way round.</p><h3>Steps</h3><ol><li>Place each LED upright on the breadboard, in a separate row. Keep them in a straight line and not touching each other.</li><li>Connect the <strong>anode</strong> (longer leg, positive) of the LED to the positive side.</li><li>Connect the <strong>cathode</strong> (shorter leg, negative) to the negative side.</li><li>Repeat for all three LEDs.</li></ol><p><em>📷 Picture to be added: three LEDs placed upright in separate rows</em></p><p><strong>⚠ Caution:</strong> Longer leg to positive, shorter leg to negative. If an LED is the wrong way round it will not light.</p><p><strong>[[VERIFY: This lesson connects the LEDs straight between 3.3V and GND with no resistor, while Lesson 2 uses resistors. Please test on the real kit and confirm whether a resistor is needed.]]</strong></p>$t$,null,$t$Longer leg = positive. Shorter leg = negative.$t$,3,15),
    (m,$t$Teacher check and power up$t$,$t$<p><strong>🎯 Objective:</strong> Get your wiring checked, power the circuit and observe the result.</p><h3>Steps</h3><ol><li>Wait for your teacher to confirm that your connections are correct.</li><li>Collect the USB cable from your teacher.</li><li>Connect the USB cable from the SmartBrains Arduino to your computer.</li><li>Observe whether all three LEDs light up.</li></ol><h3>If an LED does not light up</h3><ul><li>Is the longer leg on the positive side?</li><li>Is every wire pushed in firmly?</li><li>Is the LED in its own row?</li></ul><p>Still stuck? Raise your hand for help.</p>$t$,null,$t$Check the legs, check the wires, then ask for help.$t$,4,8);
