  insert into courses(title,slug,description,difficulty_level,is_published,total_lessons,total_quizzes,estimated_duration_minutes)
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 1: Introduction to the fire extinguisher robotic car$t$,$t$What the robot is, what it can do, where it is used and the parts you will work with.$t$,1) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What is a fire extinguisher robotic car?$t$,$t$<p><strong>🎯 Objective:</strong> Explain what the robot is and what it can do.</p><p>A fire extinguisher robotic car is a small independent robot that detects fire and automatically moves to put it out.</p><h3>What it does</h3><ul><li>Saves human lives and reduces damage by putting out fires.</li><li>Detects fire and tracks where the fire is.</li><li>Moves by itself in a fire emergency and makes smart decisions.</li></ul><h3>Where it can be used</h3><ul><li>Educational use</li><li>Disaster management</li><li>Firefighting support</li><li>Demonstrations and innovation projects</li></ul><h3>Check yourself</h3><ul><li>In your own words, what does this robot do?</li><li>Where could it help in your community?</li></ul>$t$,null,$t$Detect the fire, move to it, put it out.$t$,1,10),
    (m,$t$Meet the Arduino Uno$t$,$t$<p><strong>🎯 Objective:</strong> Say what an Arduino Uno is and name its basic parts.</p><p>The <strong>Arduino Uno</strong> is a <strong>microcontroller</strong>: a small computer on one board. It is the brain of the robot. It reads signals from sensors and decides what the motors and pump should do.</p><table><thead><tr><th>Part</th><th>What it is for</th></tr></thead><tbody><tr><td>Digital pins (D0 to D13)</td><td>Send or receive on/off signals, for example to a relay or sensor</td></tr><tr><td>Analog pins (A0 to A5)</td><td>Read varying signals from sensors</td></tr><tr><td>Power pins (5V, 3.3V, GND)</td><td>Supply power to parts and complete the circuit</td></tr></tbody></table><p><em>📷 Picture to be added: the Arduino Uno with digital pins, analog pins and power pins labelled</em></p><p><strong>[[VERIFY: The notes only list this as a lesson objective. This lesson was drafted. Check the pin counts against the board the school uses.]]</strong></p>$t$,null,$t$Arduino Uno = the microcontroller, the robot's brain.$t$,2,10),
    (m,$t$Your component list$t$,$t$<p><strong>🎯 Objective:</strong> List the parts you will use in this project.</p><p>You will work with these components. In the next lesson you will learn what each one does.</p><ul><li>Flame sensor</li><li>DC water pump</li><li>Relay module</li><li>Batteries</li><li>Arduino Uno</li><li>Motor driver</li><li>Jumper wires</li><li>Ultrasonic sensor</li><li>Breadboard</li><li>Switch</li><li>DC motors (4)</li><li>Wheels (4)</li><li>Water tank</li><li>Chassis</li></ul>$t$,null,$t$14 parts, each with a job.$t$,3,8);
