  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$Cooking food$t$,false,1),(qq,$t$Playing music at parties$t$,false,2),(qq,$t$Educational use$t$,true,3),(qq,$t$Disaster management$t$,true,4),(qq,$t$Firefighting support$t$,true,5);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 2: Components and their functions$t$,$t$Learn what each of the 14 parts does, using simple comparisons.$t$,2) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$The senses: flame sensor and ultrasonic sensor$t$,$t$<p><strong>🎯 Objective:</strong> Describe how the robot "sees" fire and obstacles.</p><table><thead><tr><th>Component</th><th>Think of it as</th><th>What it does</th></tr></thead><tbody><tr><td>Flame sensor</td><td>The robot's "eye for fire"</td><td>Detects flames by sensing the infrared (heat) light that fire gives off. Without it the robot would not know there is danger.</td></tr><tr><td>Ultrasonic sensor</td><td>The robot's eyes for obstacles</td><td>Measures distance using sound waves, so the robot does not bump into things on its way to the fire.</td></tr></tbody></table><h3>Check yourself</h3><ul><li>Which sensor finds fire? Which one finds obstacles?</li></ul>$t$,null,$t$Flame sensor = eye for fire. Ultrasonic = eyes for obstacles.$t$,1,8),
    (m,$t$The brain and the power: Arduino, motor driver, batteries and switch$t$,$t$<p><strong>🎯 Objective:</strong> Describe the parts that think and power the robot.</p><table><thead><tr><th>Component</th><th>Think of it as</th><th>What it does</th></tr></thead><tbody><tr><td>Arduino Uno</td><td>The brain</td><td>Makes decisions, controls every action and processes signals from the sensors.</td></tr><tr><td>Motor driver</td><td>A special "driver" for the motors</td><td>Helps the brain control the speed and direction of the DC motors (forward, backward, slow or fast) and protects the Arduino from motor overloads.</td></tr><tr><td>Batteries</td><td>The source of energy</td><td>Supply power to every part so the robot can move, sense fire and spray water.</td></tr><tr><td>Switch</td><td>The power button</td><td>Turns the system on and off safely and avoids sudden power surges.</td></tr></tbody></table>$t$,null,$t$Arduino thinks. Driver controls motors. Batteries power. Switch turns on and off.$t$,2,10),
    (m,$t$The body and the firefighting parts$t$,$t$<p><strong>🎯 Objective:</strong> Describe the parts that move the robot and put out the fire.</p><table><thead><tr><th>Component</th><th>Think of it as</th><th>What it does</th></tr></thead><tbody><tr><td>DC motors (4)</td><td>The legs' muscles</td><td>Drive the wheels, giving movement and speed control in different directions.</td></tr><tr><td>Wheels (4)</td><td>The feet</td><td>Allow smooth motion and direction control.</td></tr><tr><td>Chassis</td><td>The skeleton</td><td>Holds all the parts together and gives space for wiring.</td></tr><tr><td>Water tank</td><td>The storage tank</td><td>Holds the water ready to put out the fire.</td></tr><tr><td>DC water pump</td><td>The firefighting "mouth"</td><td>Sprays water only when the Arduino tells it to, through a relay.</td></tr><tr><td>Relay module</td><td>A security gate</td><td>Lets the tiny Arduino switch powerful devices like the pump safely.</td></tr><tr><td>Breadboard</td><td>A safe playground for connections</td><td>Lets you plug parts in without soldering.</td></tr><tr><td>Jumper wires</td><td>The nerves</td><td>Let electricity and signals flow between components.</td></tr></tbody></table>$t$,null,$t$The relay lets a small Arduino control a big pump.$t$,3,12),
    (m,$t$Group activity: robot component roles$t$,$t$<p><strong>🎯 Objective:</strong> Identify each real component and explain its job to your group.</p><h3>You need</h3><ul><li>A full set of the project components for your group</li></ul><h3>Steps</h3><ol><li>Divide yourselves into small groups and make sure your table has every component.</li><li>Your teacher names one component at a time. Discuss in your group what it does.</li><li>One person holds the component and states its function using the comparisons you learned.</li><li>Pass the components around so everyone holds and inspects at least three different ones.</li></ol>$t$,null,$t$Hold it, name it, explain it.$t$,4,20);
