  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 8: Programming in mBlock$t$,$t$Program the Arduino so the robot finds and puts out fire automatically.$t$,8) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Set up mBlock$t$,$t$<p><strong>🎯 Objective:</strong> Connect mBlock to your Arduino Uno.</p><h3>Steps</h3><ol><li>Open <strong>mBlock</strong> on your laptop.</li><li>Go to <strong>Devices</strong>, add the <strong>Arduino Uno</strong> and click Connect.</li><li>Make sure the board is connected through the USB cable.</li></ol><p>Wait for your teacher before you move on, so that everyone is at the same step.</p>$t$,null,$t$Devices, then Arduino Uno, then Connect.$t$,1,10),
    (m,$t$Plan the program$t$,$t$<p><strong>🎯 Objective:</strong> Explain, in words, what the program must do.</p><p>Before you place blocks, write the plan. Your robot repeats the same checks again and again:</p><ol><li>Read the <strong>flame sensor</strong>.</li><li>If a flame is detected: stop the motors and switch the <strong>pump on</strong> to spray water.</li><li>If there is no flame: drive forward.</li><li>Read the <strong>ultrasonic sensor</strong>. If an obstacle is too close: stop or turn away.</li></ol><p><em>📷 Picture to be added: the mBlock block program in Block Mode</em></p><h3>Check yourself</h3><ul><li>Which part of the plan uses the flame sensor?</li><li>Which part avoids obstacles?</li></ul><p><strong>[[VERIFY: The notes say "drag and arrange the following blocks (picture to be added)". This plan was drafted from the lesson objective. Replace it with the client's actual block order and picture.]]</strong></p>$t$,null,$t$Forever: check for fire, then drive or spray.$t$,2,15),
    (m,$t$Upload and test$t$,$t$<p><strong>🎯 Objective:</strong> Upload the program and watch the robot work.</p><h3>Steps</h3><ol><li>Switch to <strong>Block Mode</strong> under the Coding tab and arrange the blocks.</li><li>Click <strong>Upload to Arduino</strong>.</li><li>With your teacher present, light a flame at a safe distance and watch the robot. The pump should spray water to put it out.</li></ol><p><strong>⚠ Caution:</strong> Fire is dangerous. Only test with a flame when your teacher is present, keep everyone at a safe distance, keep long hair and loose clothing away, and keep water or a fire blanket nearby. Never leave a flame unattended.</p>$t$,null,$t$Upload to Arduino sends your program to the robot.$t$,3,15),
    (m,$t$Observe and discuss$t$,$t$<p><strong>🎯 Objective:</strong> Explain what the robot does and why.</p><h3>Check yourself</h3><ul><li>What happens when the flame is near the sensor?</li><li>What happens when you move it away?</li></ul>$t$,null,$t$Notice what changes when the flame moves.$t$,4,8);
