  insert into courses(title,slug,description,difficulty_level,is_published,total_lessons,total_quizzes,estimated_duration_minutes)
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 1: Introduction to robotics and automation$t$,$t$What an automatic hand sanitizer dispenser is, why it matters and how automation works.$t$,1) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What is an automatic hand sanitizer dispenser?$t$,$t$<p><strong>🎯 Objective:</strong> Explain what the project is and what it is for.</p><p>An automatic hand sanitizer dispenser is a machine that gives you sanitizer without touching it. When you put your hand near it, a small sensor sees your hand and makes the sanitizer come out. It helps keep hands clean and stops germs spreading.</p><h3>Purpose of the project</h3><p>This project aims to design and build an automatic hand sanitizer dispenser that uses sensors to detect hands and dispense sanitizer without physical contact.</p><h3>Check yourself</h3><ul><li>Why is it better not to touch the dispenser?</li></ul>$t$,null,$t$Hand near, sensor sees, sanitizer comes out.$t$,1,10),
    (m,$t$Where it is used and why it matters$t$,$t$<p><strong>🎯 Objective:</strong> Give examples of where the dispenser is used and why it is important.</p><h3>Real-life applications</h3><ul><li><strong>Health facilities</strong> (hospitals and clinics): at entrances, wards and patient rooms to promote hand hygiene and prevent infections.</li><li><strong>Schools, learning institutions and offices</strong>: at classroom doors and hallways so people sanitize their hands regularly.</li></ul><h3>Why it is important</h3><ul><li>It reduces physical contact, lowering the risk of cross-contamination between people.</li><li>It improves safety in a workplace and shows a commitment to health.</li></ul><p>Class discussion: where in your school or community could one of these dispensers be used?</p>$t$,null,$t$Less touching means fewer germs spread.$t$,2,10),
    (m,$t$Robotics and automation$t$,$t$<p><strong>🎯 Objective:</strong> Define robotics and automation and name examples of automated machines.</p><p><strong>Robotics</strong> is the branch of technology that deals with the design, construction, operation and application of robots.</p><p><strong>Automation</strong> means using robots and control systems to carry out tasks automatically with minimal human input.</p><h3>Examples of automated machines</h3><ul><li>Automatic hand sanitizer dispenser</li><li>Smart dustbin</li><li>Water pump</li><li>Industrial robotic arm</li><li>Autonomous vacuum cleaner</li></ul>$t$,null,$t$Automation = tasks done automatically with little human input.$t$,3,10),
    (m,$t$What you will need$t$,$t$<p><strong>🎯 Objective:</strong> Know the materials for the project.</p><h3>You need</h3><ul><li>Cardboard or box pieces</li><li>Glue or hot glue gun</li><li>Scissors or cutter</li><li>A pen or stick to press the sanitizer cap</li><li>A sanitizer bottle</li><li>Servo motor</li><li>Ultrasonic sensor</li><li>SmartBrains Arduino Uno board</li><li>Jumper wires</li><li>Breadboard</li></ul><p><strong>⚠ Caution:</strong> Ask an adult to help with the hot glue gun and cutter.</p>$t$,null,$t$Cardboard body, servo arm, sensor eyes, Arduino brain.$t$,4,5);
