  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$Calculator and printer$t$,false,1),(qq,$t$Microwave oven and blender$t$,false,2),(qq,$t$Ceiling fan and light bulb$t$,false,3),(qq,$t$Industrial robotic arm and autonomous vacuum cleaner$t$,true,4);
  insert into quiz_questions(quiz_id,question_text,question_type,order_index) values (q,$t$Where can automatic hand sanitizer dispensers be used?$t$,'single',4) returning id into qq;
  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$Homes, offices and schools$t$,false,1),(qq,$t$Libraries, cinemas and gyms$t$,false,2),(qq,$t$Hospitals, restaurants and shopping malls$t$,false,3),(qq,$t$All of the above$t$,true,4);
  insert into quiz_questions(quiz_id,question_text,question_type,order_index) values (q,$t$Select ALL the real importances of an automatic hand sanitizer dispenser.$t$,'multiple',5) returning id into qq;
  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$It makes sanitizer free$t$,false,1),(qq,$t$It improves safety and shows a commitment to health$t$,true,2),(qq,$t$It cooks food$t$,false,3),(qq,$t$It reduces physical contact and the risk of cross-contamination$t$,true,4),(qq,$t$It helps stop the spread of germs$t$,true,5);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 2: Project overview and components$t$,$t$Identify every component and what it does.$t$,2) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$The components and their jobs$t$,$t$<p><strong>🎯 Objective:</strong> Name each component and say what it does.</p><table><thead><tr><th>Component</th><th>What it does</th></tr></thead><tbody><tr><td>SmartBrains Arduino Uno</td><td>The brain of the project. It controls everything.</td></tr><tr><td>Ultrasonic sensor</td><td>Detects when a hand is placed near the dispenser.</td></tr><tr><td>Servo motor</td><td>Pushes out the sanitizer when the sensor is triggered.</td></tr><tr><td>Jumper wires</td><td>Connect all the components on the breadboard or the Arduino board.</td></tr><tr><td>Power supply (battery)</td><td>Provides power to the circuit.</td></tr><tr><td>Breadboard</td><td>Used to assemble and organise the circuit connections.</td></tr><tr><td>Sanitizer bottle</td><td>Holds the sanitizer.</td></tr></tbody></table><p>The Arduino has <strong>digital pins</strong> and <strong>analog pins</strong>. Your sensor and servo connect to digital pins.</p>$t$,null,$t$Arduino thinks, sensor sees, servo pushes.$t$,1,12),
    (m,$t$The ultrasonic sensor pins$t$,$t$<p><strong>🎯 Objective:</strong> Name the four pins of the ultrasonic sensor.</p><table><thead><tr><th>Sensor pin</th><th>Connects to</th><th>Job</th></tr></thead><tbody><tr><td>VCC</td><td>5V</td><td>Powers the sensor</td></tr><tr><td>GND</td><td>GND</td><td>Completes the circuit</td></tr><tr><td>TRIG</td><td>Digital pin 9 (can be any digital pin)</td><td>Sends out an ultrasonic pulse</td></tr><tr><td>ECHO</td><td>Digital pin 10 (can be any digital pin)</td><td>Receives the reflected pulse</td></tr></tbody></table>$t$,null,$t$VCC, TRIG, ECHO, GND.$t$,2,8),
    (m,$t$Types of jumper wires$t$,$t$<p><strong>🎯 Objective:</strong> Name the three types of jumper wire and organise a circuit.</p><ul><li><strong>Pin to pin</strong>: a pin on both ends.</li><li><strong>Pin to port</strong>: a pin on one end and a socket on the other.</li><li><strong>Port to port</strong>: a socket on both ends.</li></ul><h3>Your turn</h3><ol><li>Look at the components your teacher passes around.</li><li>Name each one and say what it does.</li><li>Find one wire of each type.</li></ol>$t$,null,$t$Pin = metal tip. Port = socket.$t$,3,8);
  insert into quizzes(module_id,title,description,pass_score,total_questions) values (m,$t$Components quiz$t$,$t$Check what you learned about the components.$t$,70,5) returning id into q;
