  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 5: Building the physical structure$t$,$t$Design and assemble the body of the dispenser and mount the parts neatly.$t$,5) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Materials and the plan$t$,$t$<p><strong>🎯 Objective:</strong> Gather your materials and understand what you are building.</p><p>We are building a robotic sanitizer that pours sanitizer automatically when your hand goes near it!</p><h3>You need</h3><ul><li>Cardboard or box pieces</li><li>Glue or hot glue gun</li><li>Scissors or cutter</li><li>A pen or stick to press the sanitizer cap</li><li>A sanitizer bottle</li><li>Servo motor</li><li>Ultrasonic sensor</li><li>SmartBrains Arduino Uno board</li><li>Jumper wires</li><li>Breadboard</li></ul><p><strong>⚠ Caution:</strong> Ask an adult to help with the hot glue gun and cutter.</p>$t$,null,$t$Plan before you cut.$t$,1,8),
    (m,$t$Make the body and the top$t$,$t$<p><strong>🎯 Objective:</strong> Build the box and the top for the sensor.</p><h3>Step 1: Make the body</h3><ul><li>Cut the cardboard pieces and glue them into a tall box shape, like a small building.</li><li>Leave space inside where the sanitizer bottle will fit.</li><li>Make an opening at the front for the sanitizer to come out.</li></ul><h3>Step 2: Make the top part</h3><ul><li>On top of the box, make a small flat area for the ultrasonic sensor. It is the robot's eyes that see your hand.</li></ul><p><em>📷 Picture to be added: the cardboard body with the opening at the front and the flat top</em></p>$t$,null,$t$Tall box, space for the bottle, opening at the front.$t$,2,15),
    (m,$t$Add the pen arm and the servo$t$,$t$<p><strong>🎯 Objective:</strong> Build the mechanism that presses the sanitizer cap.</p><h3>Step 3: Add the pen arm</h3><ul><li>Fix a pen or stick to one side of the box with tape or wire.</li><li>The pen should touch the top of the sanitizer cap so it can press it down when the motor moves.</li></ul><h3>Step 4: Attach the servo motor</h3><ul><li>Stick the servo motor on the side of the box, just below the pen.</li><li>Connect the pen to the servo's moving arm with a small wire or piece of string.</li><li>When the motor turns, it should push the pen, and the pen presses the cap to release the sanitizer.</li></ul><p><em>📷 Picture to be added: the pen connected to the servo arm above the bottle cap</em></p>$t$,null,$t$Servo turns, pen presses, sanitizer comes out.$t$,3,15),
    (m,$t$Place the sensor and the electronics$t$,$t$<p><strong>🎯 Objective:</strong> Mount the sensor, the Arduino and the breadboard.</p><h3>Step 5: Place the ultrasonic sensor</h3><ul><li>Fix the sensor at the top of the box, like eyes.</li><li>It should face <strong>downwards</strong> so it can see your hand when you put it below.</li></ul><h3>Step 6: Add the Arduino and the breadboard</h3><ul><li>Place the SmartBrains Arduino Uno at the bottom of the box and the breadboard on the other side.</li></ul>$t$,null,$t$Sensor faces down. Arduino at the bottom.$t$,4,10);
