  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$For the wind to pass$t$,false,1),(qq,$t$For a second pen$t$,false,2),(qq,$t$To hide the glue$t$,false,3),(qq,$t$For the sanitizer bottle to fit$t$,true,4);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 6: Wiring the project and placing the bottle$t$,$t$Connect the sensor and servo to the Arduino and load the sanitizer.$t$,6) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Wire the ultrasonic sensor$t$,$t$<p><strong>🎯 Objective:</strong> Connect the sensor to the Arduino through the breadboard.</p><p>Use jumper wires to connect the sensor, starting with the ultrasonic sensor (see Lesson 3).</p><table><thead><tr><th>Sensor pin</th><th>Connects to</th><th>Job</th></tr></thead><tbody><tr><td>VCC</td><td>5V</td><td>Powers the sensor</td></tr><tr><td>GND</td><td>GND</td><td>Completes the circuit</td></tr><tr><td>TRIG</td><td>Digital pin 9 (can be any digital pin)</td><td>Sends out an ultrasonic pulse</td></tr><tr><td>ECHO</td><td>Digital pin 10 (can be any digital pin)</td><td>Receives the reflected pulse</td></tr></tbody></table>$t$,null,$t$Sensor first: VCC 5V, GND GND, TRIG 9, ECHO 10.$t$,1,12),
    (m,$t$Wire the servo motor$t$,$t$<p><strong>🎯 Objective:</strong> Connect the servo to the Arduino.</p><p>Now connect the servo motor (see Lesson 4).</p><table><thead><tr><th>Servo wire</th><th>Colour</th><th>Connects to</th><th>Job</th></tr></thead><tbody><tr><td>VCC (power)</td><td>Red</td><td>5V</td><td>Supplies power to the servo</td></tr><tr><td>GND (ground)</td><td>Brown</td><td>GND</td><td>Completes the circuit</td></tr><tr><td>Signal</td><td>Orange</td><td>Digital pin 3</td><td>Carries control signals from the Arduino to the servo</td></tr></tbody></table><p><strong>⚠ Caution:</strong> Make sure the orange wire is connected directly to the Arduino.</p>$t$,null,$t$Servo: red and brown to the breadboard, orange to pin 3.$t$,2,12),
    (m,$t$Put the sanitizer inside$t$,$t$<p><strong>🎯 Objective:</strong> Place the bottle where the pen can press the cap.</p><ul><li>Carefully place your sanitizer bottle inside the open space in the box.</li><li>Make sure the cap is right under the pen so it can be pressed properly.</li></ul>$t$,null,$t$The cap must sit right under the pen.$t$,3,6);
