  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 7: Programming in mBlock$t$,$t$Program the dispenser so it works automatically.$t$,7) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Set up mBlock$t$,$t$<p><strong>🎯 Objective:</strong> Set up mBlock to program your SmartBrains Arduino Uno.</p><h3>You need</h3><ul><li>SmartBrains Arduino software (mBlock)</li><li>SmartBrains Arduino Uno</li><li>USB cable</li></ul><h3>Steps</h3><ol><li>Search for <strong>mBlock</strong>, open it and choose <strong>Code with blocks</strong>.</li><li>Delete <strong>CyberPi</strong> and add the <strong>Arduino Uno</strong> device.</li><li>Add the extension for the ultrasonic sensor.</li><li>Connect the Arduino to the laptop with the USB cable (this also powers it).</li></ol><p><strong>[[VERIFY: The notes say "add an extension for the ultrasonic sensor PCM". Confirm the exact extension name.]]</strong></p>$t$,null,$t$Delete CyberPi, add Arduino Uno.$t$,1,12),
    (m,$t$Plan the program$t$,$t$<p><strong>🎯 Objective:</strong> Explain, in words, how distance controls the dispenser.</p><p>Your program repeats these checks over and over:</p><ol><li>Read the distance from the <strong>ultrasonic sensor</strong>.</li><li>If the distance is smaller than a set value, a hand is near: turn the <strong>servo</strong> so the pen presses the cap.</li><li>Wait a moment, then turn the servo back so the pen lifts.</li><li>If the distance is larger, do nothing.</li></ol><p><em>📷 Picture to be added: the mBlock blocks for the sanitizer program</em></p><h3>Check yourself</h3><ul><li>What does the sensor measure?</li><li>What does the servo do when a hand is near?</li><li>How does distance affect when the sanitizer comes out?</li></ul><p><strong>[[VERIFY: The notes say "drag the code blocks as instructed by the illustration (image to be inserted)". This plan was drafted. Replace it with the client's actual blocks, including the distance value and servo angles.]]</strong></p>$t$,null,$t$Near hand means the servo presses. Far hand means nothing happens.$t$,2,15),
    (m,$t$Upload and test$t$,$t$<p><strong>🎯 Objective:</strong> Upload the program and watch the dispenser work.</p><h3>Steps</h3><ol><li>Drag the code blocks as shown in the illustration.</li><li>Click the <strong>Upload</strong> button on the mBlock page.</li><li>Wait for the upload to complete.</li><li>Place your hand near the sensor.</li></ol><h3>What should happen</h3><ol><li>The ultrasonic sensor sees your hand.</li><li>It sends a message to the Arduino.</li><li>The servo motor moves.</li><li>The pen presses the sanitizer bottle.</li><li>Sanitizer comes out to clean your hands!</li></ol>$t$,null,$t$Upload, wait, then test with your hand.$t$,3,12);
  insert into quizzes(module_id,title,description,pass_score,total_questions) values (m,$t$Programming quiz$t$,$t$Check what you learned about programming the dispenser.$t$,70,5) returning id into q;
